type Section = "dashboard" | "projects" | "tests" | "generator" | "api" | "automation" | "executions" | "defects" | "intelligence" | "pipelines" | "releases" | "analytics" | "team" | "audit" | "assistant";

const navigation: Array<{ label: string; section: Section; icon: typeof LayoutDashboard; group: string }> = [
  { label: "Overview", section: "dashboard", icon: LayoutDashboard, group: "Workspace" },
  { label: "Projects", section: "projects", icon: Boxes, group: "Workspace" },
  { label: "Test library", section: "tests", icon: ClipboardCheck, group: "Quality" },
  { label: "AI test generator", section: "generator", icon: Sparkles, group: "Quality" },
  { label: "API testing", section: "api", icon: Network, group: "Quality" },
  { label: "UI automation", section: "automation", icon: Code2, group: "Quality" },
  { label: "Execution center", section: "executions", icon: Play, group: "Quality" },
  { label: "Defects", section: "defects", icon: AlertTriangle, group: "Intelligence" },
  { label: "Failure intelligence", section: "intelligence", icon: BrainCircuit, group: "Intelligence" },
  { label: "CI/CD quality gate", section: "pipelines", icon: GitBranch, group: "Delivery" },
  { label: "Release readiness", section: "releases", icon: ShieldCheck, group: "Delivery" },
  { label: "Engineering analytics", section: "analytics", icon: Activity, group: "Delivery" },
  { label: "Team", section: "team", icon: Users, group: "Admin" },
  { label: "Audit log", section: "audit", icon: TerminalSquare, group: "Admin" },
  { label: "Forge Assistant", section: "assistant", icon: Bot, group: "Admin" },
];

const dateText = (value: Date | string | number | null | undefined) => value ? new Date(value).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }) : "—";

function StatusPill({ value }: { value: string }) {
  const normalized = value.replaceAll("_", " ");
  const tone = /pass|ready|active|healthy|released|stable/i.test(value) ? "good" : /critical|fail|block|at risk/i.test(value) ? "danger" : "warn";
  return <span className={cn("status-pill", tone)}><span className="status-dot" />{normalized}</span>;
}

function MetricCard({ label, value, detail, accent, icon: Icon }: { label: string; value: string | number; detail: string; accent: string; icon: typeof Gauge }) {
  return <div className="metric-card">
    <div className="metric-label"><span>{label}</span><span className={cn("metric-icon", accent)}><Icon /></span></div>
    <div className="metric-value">{value}</div>
    <p className="metric-detail">{detail}</p>
  </div>;
}

function SectionHeading({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description: string; actions?: React.ReactNode }) {
  return <header className="section-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{description}</p></div>{actions && <div className="section-actions">{actions}</div>}</header>;
}

export default function Workspace() {
  const [location, setLocation] = useLocation();
  const { user } = useAuth();
  const workspaceBase = location.startsWith("/workspace") ? "/workspace" : "/app";
  const pieces = location.split("/");
  const requested = pieces[2] as Section | undefined;
  const section: Section = navigation.some(item => item.section === requested) ? requested! : "dashboard";
  const [menuOpen, setMenuOpen] = useState(false);
  const viewerRole = user?.role ?? (workspaceBase === "/app" ? "manager" : "user");
  const canView = (item: { section: Section }) => canAccessWorkspaceSection(viewerRole, item.section);
  const isRestrictedRoute = workspaceBase === "/workspace" && !canAccessWorkspaceSection(viewerRole, section);
  useEffect(() => { if (isRestrictedRoute) setLocation("/workspace"); }, [isRestrictedRoute, setLocation]);

  if (isRestrictedRoute) return <div className="workspace-loading">Applying workspace access policy…</div>;

  return <div className="app-shell">
    <aside className={cn("app-sidebar", menuOpen && "is-open")}>
      <div className="brand-block"><button aria-label="Go to landing page" onClick={() => setLocation("/")} className="brand-mark"><span className="brand-mark-core" /></button><div><strong>QualityForge</strong><span>AI QUALITY INTELLIGENCE</span></div><button className="mobile-close" aria-label="Close navigation" onClick={() => setMenuOpen(false)}><X /></button></div>
      <div className="workspace-switcher"><span className="switcher-symbol">A</span><div><b>Atlas Commerce</b><small>release/2026.08</small></div><ChevronRight /></div>
      <nav>{["Workspace", "Quality", "Intelligence", "Delivery", "Admin"].map(group => { const items = navigation.filter(item => item.group === group && canView(item)); return items.length ? <div className="nav-group" key={group}><p>{group}</p>{items.map(item => { const Icon = item.icon; return <button key={item.section} onClick={() => { setLocation(workspaceRoute(workspaceBase as "/app" | "/workspace", item.section)); setMenuOpen(false); }} className={cn("nav-item", section === item.section && "active")}><Icon /><span>{item.label}</span>{item.section === "defects" && <em>2</em>}</button>; })}</div> : null; })}</nav>
      <div className="sidebar-bottom"><div className="health-brief"><span className="pulse-live" /> <b>Systems nominal</b><small>3 monitored services</small></div><button onClick={() => toast.message("Personal settings are available in the full product.")} className="account-mini"><span>MC</span><div><b>Maya Chen</b><small>Engineering Manager</small></div><ChevronRight /></button></div>
    </aside>
    <main className="app-main">
      <div className="app-topbar"><div className="topbar-left"><button className="menu-trigger" onClick={() => setMenuOpen(true)} aria-label="Open navigation"><Menu /></button><div className="breadcrumb"><span>Atlas Commerce</span><ChevronRight /><b>{navigation.find(item => item.section === section)?.label}</b></div></div><div className="topbar-actions"><button className="command-trigger" onClick={() => toast.message("Command menu is ready for keyboard shortcuts in the full product.")}><Command /> <span>Search workspace</span><kbd>⌘ K</kbd></button><button className="icon-action" onClick={() => toast.message("You have 2 release-risk notifications.")}><CircleDot /><i /></button><Button onClick={() => setLocation(`${workspaceBase}/generator`)} className="create-button"><Plus /> New</Button></div></div>
      <div className="workspace-content">{section === "dashboard" && <Dashboard onNavigate={value => setLocation(`${workspaceBase}/${value}`)} />}{section === "projects" && <Projects />}{section === "tests" && <TestLibrary />}{section === "generator" && <TestGenerator onNavigate={value => setLocation(`${workspaceBase}/${value}`)} />}{section === "api" && <ApiTesting />}{section === "automation" && <Automation />}{section === "executions" && <Executions />}{section === "defects" && <Defects />}{section === "intelligence" && <FailureIntelligence />}{section === "pipelines" && <Pipelines />}{section === "releases" && <Releases />}{section === "analytics" && <Analytics />}{section === "team" && <Team />}{section === "audit" && <Audit />}{section === "assistant" && <Assistant />}</div>
    </main>
  </div>;
}

function Dashboard({ onNavigate }: { onNavigate: (section: Section) => void }) {
  const { data, isLoading } = trpc.overview.get.useQuery();
  if (isLoading || !data) return <WorkspaceLoading />;
  const metrics = data.metrics;
  const trend = data.qualityTrend.map((value, index) => ({ day: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun", "Mon", "Today"][index], value }));
  return <div className="workspace-section dashboard"><SectionHeading eyebrow="Release control room" title="Quality signal, at a glance." description="Atlas Commerce is nearing release approval. One systemic risk needs attention before production promotion." actions={<><Button variant="outline" onClick={() => onNavigate("analytics")} className="soft-button"><Activity /> View analytics</Button><Button onClick={() => onNavigate("generator")} className="primary-button"><Sparkles /> Generate tests</Button></>} />
    <div className="release-banner"><div className="release-orb"><span>{metrics.releaseScore}</span><small>/100</small></div><div><p className="eyebrow">Current release · 2026.08.12-rc.3</p><h2>Release is <span className="warning-text">nearly ready</span></h2><p>Pass rate and API health are in range. Close or mitigate the payment contract defect to clear the remaining quality gate.</p></div><div className="release-stats"><div><span>Quality score</span><b>{metrics.qualityScore}</b></div><div><span>Critical defects</span><b className="danger-text">{metrics.criticalDefects}</b></div><Button variant="outline" onClick={() => onNavigate("releases")}>Review decision <ArrowRight /></Button></div></div>
    <div className="metric-grid"><MetricCard label="Test pass rate" value={`${metrics.passRate}%`} detail="+2.4% vs last run" accent="cyan" icon={ClipboardCheck} /><MetricCard label="Automation coverage" value={`${metrics.coverage}%`} detail="12 checks added this sprint" accent="violet" icon={Zap} /><MetricCard label="API health" value={`${metrics.apiHealth}%`} detail="p95 284ms · within SLO" accent="green" icon={Network} /><MetricCard label="Open defects" value={metrics.defects} detail={`${metrics.criticalDefects} require a release decision`} accent="coral" icon={AlertTriangle} /></div>
    <div className="dashboard-grid"><section className="panel trend-panel"><div className="panel-heading"><div><h3>Quality score trajectory</h3><p>Composite release signal over the last 9 runs</p></div><Badge variant="outline" className="range-badge">Last 14 days</Badge></div><div className="chart-wrap"><ResponsiveContainer width="100%" height={245}><AreaChart data={trend}><defs><linearGradient id="qualityArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#67d7e2" stopOpacity={0.32}/><stop offset="100%" stopColor="#67d7e2" stopOpacity={0}/></linearGradient></defs><XAxis dataKey="day" tickLine={false} axisLine={false} tick={{ fill: "#81909b", fontSize: 11 }} dy={12}/><YAxis domain={[70, 100]} tickLine={false} axisLine={false} tick={{ fill: "#81909b", fontSize: 11 }} width={30}/><Tooltip contentStyle={{ background: "#10171d", border: "1px solid #26333e", borderRadius: 10 }} labelStyle={{ color: "#f4f8fa" }}/><Area type="monotone" dataKey="value" stroke="#75dde6" strokeWidth={2.5} fill="url(#qualityArea)"/></AreaChart></ResponsiveContainer></div></section>
      <section className="panel failure-panel"><div className="panel-heading"><div><h3>Failure concentration</h3><p>Across the last 24 hours</p></div><button onClick={() => onNavigate("intelligence")} className="quiet-link">Investigate <ArrowRight /></button></div><div className="failure-content"><ResponsiveContainer width="47%" height={180}><PieChart><Pie data={data.failureGroups} dataKey="value" nameKey="name" innerRadius={51} outerRadius={72} paddingAngle={5}>{data.failureGroups.map(item => <Cell key={item.name} fill={item.color} stroke="transparent" />)}</Pie></PieChart></ResponsiveContainer><div className="failure-list">{data.failureGroups.map(item => <div key={item.name}><span className="legend-color" style={{ background: item.color }} /><p>{item.name}</p><b>{item.value}%</b></div>)}</div></div></section></div>
    <div className="dashboard-grid lower-grid"><section className="panel execution-panel"><div className="panel-heading"><div><h3>Recent test executions</h3><p>Live execution activity across environments</p></div><button onClick={() => onNavigate("executions")} className="quiet-link">Open center <ArrowRight /></button></div><div className="data-list">{data.executions.slice(0, 4).map(execution => <div className="execution-row" key={execution.id}><span className="run-icon"><Play /></span><div><b>{execution.name}</b><small>{execution.environment} · {dateText(execution.startedAt)}</small></div><div className="execution-numbers"><b>{execution.passedTests}/{execution.totalTests}</b><small>passed</small></div><StatusPill value={execution.status} /></div>)}</div></section>
      <section className="panel alert-panel"><div className="panel-heading"><div><h3>Release risks</h3><p>Require an owner or decision</p></div><button onClick={() => onNavigate("defects")} className="quiet-link">View all <ArrowRight /></button></div><div className="risk-stack">{data.defects.slice(0, 3).map(defect => <button onClick={() => onNavigate("defects")} key={defect.id} className="risk-row"><span className={cn("risk-mark", defect.severity)}><AlertTriangle /></span><div><small>{defect.key} · {defect.environment}</small><b>{defect.title}</b></div><ChevronRight /></button>)}</div></section></div>
  </div>;
}

function Projects() {
  const { data, isLoading } = trpc.projects.list.useQuery();
  const utils = trpc.useUtils(); const [editing, setEditing] = useState<null | { id?: number; name: string; description: string; owner: string; stack: string }>(null);
  const [detailId, setDetailId] = useState<number | null>(null);
  const refresh = () => utils.projects.list.invalidate();
  const create = trpc.projects.create.useMutation({ onSuccess: () => { toast.success("Project created"); setEditing(null); refresh(); }, onError: error => toast.error(error.message) });
  const update = trpc.projects.update.useMutation({ onSuccess: () => { toast.success("Project updated"); setEditing(null); refresh(); }, onError: error => toast.error(error.message) });
  const archive = trpc.projects.archive.useMutation({ onSuccess: () => { toast.success("Project archived"); refresh(); }, onError: error => toast.error(error.message) });
  const submit = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!editing) return; const form = new FormData(event.currentTarget); const payload = { name: String(form.get("name")), description: String(form.get("description")), owner: String(form.get("owner")), stack: String(form.get("stack")).split(",").map(item => item.trim()).filter(Boolean) }; if (editing.id) update.mutate({ id: editing.id, ...payload }); else create.mutate(payload); };
  const detail = data?.find(project => project.id === detailId); return <div className="workspace-section"><SectionHeading eyebrow="Workspace inventory" title="Projects" description="Quality posture across the applications your release program depends on." actions={<Button onClick={() => setEditing({ name: "", description: "", owner: "Maya Chen", stack: "React, API" })} className="primary-button"><Plus /> New project</Button>} />{editing && <form className="creation-panel project-editor" onSubmit={submit}><div><label>Project name<Input required name="name" defaultValue={editing.name} placeholder="e.g. Orbit Billing" /></label><label>Owner<Input required name="owner" defaultValue={editing.owner} /></label><label>Technology stack<Input required name="stack" defaultValue={editing.stack} placeholder="React, FastAPI" /></label></div><label>Description<Textarea required name="description" defaultValue={editing.description} placeholder="Explain the project mission and scope." /></label><div className="form-actions"><Button type="button" variant="ghost" onClick={() => setEditing(null)}>Cancel</Button><Button type="submit" disabled={create.isPending || update.isPending}>{create.isPending || update.isPending ? <Loader2 className="spin" /> : <Check />} {editing.id ? "Save changes" : "Create project"}</Button></div></form>}{detail && <section className="panel project-detail"><div className="panel-heading"><div><p className="eyebrow">Project detail</p><h3>{detail.name}</h3><p>{detail.description}</p></div><Button variant="outline" onClick={() => setDetailId(null)}><X /> Close</Button></div><div className="detail-facts"><div><small>OWNER</small><b>{detail.owner}</b></div><div><small>STATUS</small><StatusPill value={detail.status} /></div><div><small>QUALITY SCORE</small><b>{detail.qualityScore} / 100</b></div><div><small>LAST DEPLOYMENT</small><b>{dateText(detail.lastDeploymentAt)}</b></div></div><div className="stack-row">{detail.stack.map((item: string) => <span key={item}>{item}</span>)}</div></section>}{isLoading ? <WorkspaceLoading /> : <div className="project-grid">{data?.map(project => <article key={project.id} className="project-card"><div className="project-card-top"><span className="project-glyph">{project.name.charAt(0)}</span><StatusPill value={project.status} /></div><h3>{project.name}</h3><p>{project.description}</p><div className="stack-row">{project.stack.map((item: string) => <span key={item}>{item}</span>)}</div><div className="project-score"><div><small>QUALITY SCORE</small><b>{project.qualityScore}</b></div><div className="score-bar"><i style={{ width: `${project.qualityScore}%` }} /></div></div><footer><span>Owner · {project.owner}</span><span>{project.status === "archived" ? "Archived" : `Deployed ${dateText(project.lastDeploymentAt)}`}</span></footer><div className="project-actions"><button onClick={() => setDetailId(project.id)}>View detail</button><button onClick={() => setEditing({ id: project.id, name: project.name, description: project.description || "", owner: project.owner, stack: project.stack.join(", ") })}>Edit</button>{project.status !== "archived" && <button onClick={() => archive.mutate({ id: project.id })}>Archive</button>}</div></article>)}</div>}</div>;
}

function TestLibrary() {
  const [search, setSearch] = useState("");
  const [type, setType] = useState("all");
  const input = useMemo(() => ({ search: search || undefined }), [search]);
  const { data, isLoading } = trpc.testCases.list.useQuery(input);
  const [isCreating, setIsCreating] = useState(false);
  const create = trpc.testCases.create.useMutation({ onSuccess: result => { toast.success(`${result.key} added to the test library`); setIsCreating(false); }, onError: error => toast.error(error.message) });
  const displayed = data?.filter(item => type === "all" || item.testType === type) ?? [];
  return <div className="workspace-section"><SectionHeading eyebrow="Quality assets" title="Test library" description="Search, triage, and grow the automation catalog behind your release decisions." actions={<Button className="primary-button" onClick={() => setIsCreating(!isCreating)}><Plus /> New test case</Button>} />
    {isCreating && <form className="creation-panel" onSubmit={event => { event.preventDefault(); const form = new FormData(event.currentTarget); create.mutate({ name: String(form.get("name")), description: String(form.get("description")), testType: String(form.get("type")) as "api", priority: String(form.get("priority")) as "medium" }); }}><div><label>Test name<Input required name="name" placeholder="e.g. Validate failed card payment recovery" /></label><label>Test type<select name="type" defaultValue="api"><option value="api">API</option><option value="e2e">End-to-end</option><option value="ui">UI</option><option value="integration">Integration</option><option value="regression">Regression</option></select></label><label>Priority<select name="priority" defaultValue="medium"><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></label></div><label>Description<Textarea required name="description" placeholder="Document the intent, acceptance criteria, and expected signal." /></label><div className="form-actions"><Button type="button" variant="ghost" onClick={() => setIsCreating(false)}>Cancel</Button><Button disabled={create.isPending} type="submit">{create.isPending && <Loader2 className="spin" />} Create test case</Button></div></form>}
    <div className="toolbar"><div className="search-input"><Search /><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search name or test key..." /></div><select value={type} onChange={event => setType(event.target.value)}><option value="all">All test types</option><option value="api">API</option><option value="ui">UI</option><option value="e2e">End-to-end</option><option value="integration">Integration</option><option value="regression">Regression</option></select><span>{displayed.length} visible tests</span></div>
    <div className="table-panel"><div className="table-head test-table"><span>Test case</span><span>Type</span><span>Priority</span><span>Automation</span><span>Owner</span><span>Status</span></div>{isLoading ? <WorkspaceLoading /> : displayed.map(item => <div className="table-row test-table" key={item.id}><div><b>{item.name}</b><small>{item.key} · {item.tags.join(" · ")}</small></div><span className="type-chip">{item.testType}</span><span className={cn("priority-chip", item.priority)}>{item.priority}</span><span>{item.automationStatus}</span><span>{item.owner}</span><StatusPill value={item.status} /></div>)}</div>
  </div>;
}

function TestGenerator({ onNavigate }: { onNavigate: (section: Section) => void }) {
  const [feature, setFeature] = useState("Checkout payment confirmation with saved payment methods");
  const [endpoint, setEndpoint] = useState("POST /v1/checkout/confirm");
  const [criteria, setCriteria] = useState("Authorized customers must receive exactly one order confirmation. The workflow must not create a duplicate charge if confirmation is retried.");
  const [result, setResult] = useState<Array<{ title: string; type: string; priority: string; scenario: string }> | null>(null);
  const generate = trpc.ai.generateTests.useMutation({ onSuccess: payload => { setResult(payload.tests); toast.success(payload.source === "ai" ? "AI test suite generated" : "Guided quality test suite generated"); }, onError: error => toast.error(error.message) });
  const create = trpc.testCases.create.useMutation({ onSuccess: data => toast.success(`${data.key} saved to the library`) });
  return <div className="workspace-section generator-page"><SectionHeading eyebrow="AI-assisted design" title="AI Test Generator" description="Turn implementation context into a decision-ready test suite, then refine and save the work your team will automate." /><div className="generator-layout"><section className="panel generator-input"><div className="panel-heading"><div><h3>Describe the behavior</h3><p>Provide enough context for a useful quality model.</p></div><Sparkles className="cyan-icon" /></div><label>Feature description<Textarea value={feature} onChange={event => setFeature(event.target.value)} /></label><label>API endpoint <Input value={endpoint} onChange={event => setEndpoint(event.target.value)} /></label><label>Acceptance criteria<Textarea value={criteria} onChange={event => setCriteria(event.target.value)} /></label><Button disabled={generate.isPending || feature.trim().length < 3} className="primary-button full-button" onClick={() => generate.mutate({ feature, endpoint, criteria })}>{generate.isPending ? <><Loader2 className="spin" /> Designing test suite…</> : <><Sparkles /> Generate test cases</>}</Button><p className="generator-footnote"><ShieldCheck /> The generator covers functional, negative, boundary, security, regression, and API-oriented scenarios.</p></section>
    <section className="generated-panel"><div className="generated-heading"><div><p className="eyebrow">Generation output</p><h2>{result ? `${result.length} test scenarios prepared` : "A thoughtful suite starts with context."}</h2></div>{result && <Button variant="outline" onClick={() => generate.mutate({ feature, endpoint, criteria })}><Sparkles /> Regenerate</Button>}</div>{result ? <div className="generated-list">{result.map((test, index) => <article className="generated-test" key={`${test.title}-${index}`}><div><span className="test-index">0{index + 1}</span><div><div className="generated-meta"><span>{test.type}</span><span className={cn("priority-chip", test.priority.toLowerCase())}>{test.priority}</span></div><h3 contentEditable suppressContentEditableWarning>{test.title}</h3><p contentEditable suppressContentEditableWarning>{test.scenario}</p></div></div><button aria-label="Save generated test" onClick={() => create.mutate({ name: test.title, description: test.scenario, testType: test.type.toLowerCase().includes("api") ? "api" : "regression", priority: test.priority.toLowerCase() === "critical" ? "critical" : test.priority.toLowerCase() === "high" ? "high" : "medium" })}><Plus /></button></article>)}</div> : <div className="generator-empty"><BrainCircuit /><h3>Design with an experienced QA lens</h3><p>QualityForge turns requirements into testable scenarios and keeps the reasoning visible enough for your team to own.</p><button onClick={() => onNavigate("tests")}>Browse existing coverage <ArrowRight /></button></div>}</section></div></div>;
}

function ApiTestingLegacy() {
  const [method, setMethod] = useState("POST"); const [endpoint, setEndpoint] = useState("/v1/checkout/confirm"); const [body, setBody] = useState('{\n  "cartId": "cart_demo_018",\n  "paymentMethodId": "pm_saved_4242"\n}'); const [ran, setRan] = useState(false); const [running, setRunning] = useState(false);
  const execute = () => { setRunning(true); setRan(false); setTimeout(() => { setRunning(false); setRan(true); }, 850); }; const simulation = apiSimulationResult(ran);
  return <div className="workspace-section"><SectionHeading eyebrow="Contract confidence" title="API testing workspace" description="Compose a request, validate its contract, and capture an execution-quality signal." actions={<Button onClick={execute} disabled={running} className="primary-button">{running ? <Loader2 className="spin" /> : <Play />} {running ? "Running…" : "Run request"}</Button>} /><div className="api-layout"><section className="panel request-panel"><div className="request-line"><select value={method} onChange={event => setMethod(event.target.value)}><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select><Input value={endpoint} onChange={event => setEndpoint(event.target.value)} /></div><div className="api-tabs"><span className="active">Body</span><span>Headers <em>2</em></span><span>Parameters</span><span>Assertions <em>5</em></span></div><Textarea className="code-area" value={body} onChange={event => setBody(event.target.value)} /><div className="assertion-list"><p>Automated assertions</p>{["Response status is 200", "Required orderId is present", "JSON matches confirmation schema", "Response time is below 500ms"].map(assertion => <span key={assertion}><Check /> {assertion}</span>)}</div></section><section className="panel response-panel"><div className="panel-heading"><div><h3>Execution response</h3><p>{ran ? "Latest run · just now" : "Run a request to inspect its response"}</p></div>{ran && <StatusPill value="passed" />}</div>{ran ? <><div className="response-stats"><div><small>STATUS</small><b className="good-text">200 OK</b></div><div><small>TIME</small><b>284 ms</b></div><div><small>SIZE</small><b>1.2 kB</b></div></div><pre className="response-code">{`{
  "orderId": "ord_01J9F2A7QZ",
  "status": "confirmed",
  "payment": { "state": "authorized" },
  "links": { "receipt": "/v1/orders/ord_01J9F2A7QZ" }
}`}</pre><div className="validation-result"><ShieldCheck /><div><b>Contract checks passed</b><p>Response matched the expected checkout confirmation schema and performance threshold.</p></div></div></> : <div className="response-empty"><Network /><h3>Ready to validate a contract</h3><p>Every response is evaluated against the checks in your test definition.</p></div>}</section></div></div>;
}

function ApiTesting() {
  const [ran, setRan] = useState(false); const [running, setRunning] = useState(false); const [endpoint, setEndpoint] = useState("/v1/checkout/confirm"); const simulation = apiSimulationResult(ran);
  const run = () => { setRunning(true); setRan(false); setTimeout(() => { setRunning(false); setRan(true); }, 850); };
  return <div className="workspace-section"><SectionHeading eyebrow="Contract confidence" title="API testing workspace" description="Compose a request, validate its contract, and capture an execution-quality signal." actions={<ApiRunButton running={running} onRun={run} />} /><div className="api-layout"><section className="panel request-panel"><div className="request-line"><select defaultValue="POST"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select><Input value={endpoint} onChange={event => setEndpoint(event.target.value)} /></div><div className="api-tabs"><span className="active">Body</span><span>Headers <em>2</em></span><span>Parameters</span><span>Assertions <em>5</em></span></div><Textarea className="code-area" defaultValue={'{\n  "cartId": "cart_demo_018",\n  "paymentMethodId": "pm_saved_4242"\n}'} /><div className="assertion-list"><p>Automated assertions</p>{["Response status is 200", "Required orderId is present", "JSON matches confirmation schema", "Response time is below 500ms"].map(item => <span key={item}><Check /> {item}</span>)}</div></section><section className="panel response-panel"><div className="panel-heading"><div><h3>Execution response</h3><p>{ran ? "Latest run · just now" : "Run a request to inspect its response"}</p></div>{ran && <StatusPill value={simulation.state} />}</div>{ran ? <><div className="response-stats"><div><small>STATUS</small><b className="good-text">{simulation.status}</b></div><div><small>TIME</small><b>{simulation.duration}</b></div><div><small>SIZE</small><b>1.2 kB</b></div></div><pre className="response-code">{`{\n  "orderId": "ord_01J9F2A7QZ",\n  "status": "confirmed",\n  "payment": { "state": "authorized" }\n}`}</pre><div className="validation-result"><ShieldCheck /><div><b>Contract checks passed</b><p>Response matched the expected checkout confirmation schema and performance threshold.</p></div></div></> : <div className="response-empty"><Network /><h3>Ready to validate a contract</h3><p>Every response is evaluated against the checks in your test definition.</p></div>}</section></div></div>;
}

function Automation() {
  const [running, setRunning] = useState(false); const [complete, setComplete] = useState(false);
  const start = () => { setRunning(true); setComplete(false); setTimeout(() => { setRunning(false); setComplete(true); }, 1300); };
  return <div className="workspace-section"><SectionHeading eyebrow="Browser confidence" title="UI automation" description="Model Playwright-style browser scenarios and see the execution narrative your team would investigate." actions={<Button disabled={running} onClick={start} className="primary-button">{running ? <Loader2 className="spin" /> : <Play />} {running ? "Executing…" : "Start execution"}</Button>} /><div className="automation-layout"><section className="panel scenario-panel"><h3>Checkout recovery scenario</h3><p>Run the saved Chrome scenario against the staging application.</p><div className="scenario-meta"><span><small>APPLICATION</small><b>staging.atlas.example</b></span><span><small>BROWSER</small><b>Chromium 129</b></span><span><small>ENVIRONMENT</small><b>Staging</b></span></div><ol className="step-list">{["Open the checkout page with a saved cart", "Select the saved Visa payment method", "Confirm payment and wait for the order receipt", "Assert confirmation appears exactly once"].map((step, index) => <li key={step} className={cn(running && index < 3 && "running", complete && "complete")}><span>{complete && index < 3 ? <Check /> : index + 1}</span>{step}</li>)}</ol></section><section className="panel execution-feed"><div className="panel-heading"><div><h3>Execution log</h3><p>Latest browser trace</p></div>{complete ? <StatusPill value="failed" /> : running ? <StatusPill value="running" /> : <StatusPill value="ready" />}</div>{(running || complete) ? <div className="terminal-log"><p><i>14:02:11.184</i> browser.chromium.launch()</p><p><i>14:02:12.008</i> goto(https://staging.atlas.example/checkout)</p><p><i>14:02:13.611</i> click([data-test=payment-method-saved])</p><p><i>14:02:14.233</i> click([data-test=confirm-payment])</p>{complete && <><p className="error-line"><i>14:02:15.720</i> assertion failed: expected 1 confirmation, received 2</p><p><i>14:02:16.019</i> screenshot captured · failure location: confirmation banner</p></>}</div> : <div className="response-empty"><Code2 /><h3>Scenario prepared</h3><p>Start an execution to stream the trace and capture results.</p></div>}{complete && <div className="failure-callout"><AlertTriangle /><div><b>Potential duplicate confirmation</b><p>Test failed after a 4.9s run. Capture is ready for defect triage.</p></div><Button variant="outline" onClick={() => toast.success("A defect draft has been prepared from this trace.")}>Create defect</Button></div>}</section></div></div>;
}

function Executions() { const { data, isLoading } = trpc.overview.get.useQuery(); const [running, setRunning] = useState(false); const [suite, setSuite] = useState("Checkout Release Candidate"); const [environment, setEnvironment] = useState("Staging"); const [stopped, setStopped] = useState(false); const start = () => { setStopped(false); setRunning(true); setTimeout(() => setRunning(false), 1400); }; const stop = () => { setRunning(false); setStopped(true); }; const progress = executionProgress(running, stopped); return <div className="workspace-section"><SectionHeading eyebrow="Central execution" title="Test Execution Center" description="Coordinate suites, observe live run state, and make failure response repeatable." actions={<div className="section-actions"><select value={suite} onChange={event => setSuite(event.target.value)}><option>Checkout Release Candidate</option><option>Identity Core</option><option>Analytics API</option></select><select value={environment} onChange={event => setEnvironment(event.target.value)}><option>Staging</option><option>Production</option></select>{running ? <Button onClick={stop} variant="outline" className="soft-button"><X /> Stop execution</Button> : <Button onClick={start} className="primary-button"><Play /> {stopped ? "Restart execution" : "Start execution"}</Button>}</div>} /><div className="execution-overview"><div className="run-control"><p className="eyebrow">Selected suite</p><h2>{suite}</h2><div className="control-tags"><span>{environment}</span><span>12 tests</span><span>Regression</span></div><div className="progress-track"><i style={{ width: `${progress.percent}%` }} /></div><div className="progress-caption"><span>{progress.label}</span><b>{progress.percent}%</b></div></div><div className="run-health"><div><b>10</b><span>Passed</span></div><div><b className="danger-text">2</b><span>Failed</span></div><div><b>0</b><span>Skipped</span></div><div><b>{stopped ? "Stopped" : "4m 19s"}</b><span>Duration</span></div></div></div><section className="panel"><div className="panel-heading"><div><h3>Execution history</h3><p>Recent runs across test suites and environments</p></div><Button variant="outline" onClick={start}>{running ? <Loader2 className="spin" /> : <Play />} Rerun failed</Button></div>{isLoading ? <WorkspaceLoading /> : <div className="data-list">{data?.executions.map(execution => <div className="execution-row" key={execution.id}><span className="run-icon"><FlaskConical /></span><div><b>{execution.name}</b><small>{execution.environment} · {dateText(execution.startedAt)}</small></div><div className="execution-numbers"><b>{execution.passedTests}/{execution.totalTests}</b><small>passed · {execution.durationSeconds}s</small></div><StatusPill value={execution.status} /></div>)}</div>}</section></div>; }

function DefectsLegacy() { const { data, isLoading } = trpc.defects.list.useQuery(); const [activeId, setActiveId] = useState<number | null>(null); const active = data?.find(item => item.id === activeId) ?? data?.[0]; const update = trpc.defects.update.useMutation({ onSuccess: () => toast.success("Defect workflow updated") }); const analyze = trpc.ai.analyzeDefect.useMutation(); return <div className="workspace-section"><SectionHeading eyebrow="Defect operations" title="Defects" description="Move quickly from a quality signal to responsible triage, evidence, and root-cause direction." actions={<Button onClick={() => toast.message("New defect creation is represented in this demo workspace.")} className="primary-button"><Plus /> Create defect</Button>} /><div className="defect-layout"><section className="panel defect-list"><div className="panel-heading"><div><h3>Open triage queue</h3><p>{data?.filter(item => !["resolved", "closed"].includes(item.status)).length ?? 0} active defects</p></div><Search className="cyan-icon" /></div>{isLoading ? <WorkspaceLoading /> : data?.map(defect => <button className={cn("defect-item", active?.id === defect.id && "selected")} onClick={() => { setActiveId(defect.id); analyze.reset(); }} key={defect.id}><div><span className={cn("severity-bar", defect.severity)} /><div><small>{defect.key} · {defect.environment}</small><b>{defect.title}</b><span>{defect.assignee || "Unassigned"} · updated {dateText(defect.updatedAt)}</span></div></div><StatusPill value={defect.status} /></button>)}</section><section className="defect-detail">{active && <><div className="detail-header"><div><div className="detail-kicker"><span className={cn("priority-chip", active.severity)}>{active.severity}</span><span>{active.key}</span></div><h2>{active.title}</h2><p>{active.description}</p></div><select value={active.status} onChange={event => { const next = event.target.value; if (!canUpdateDefectStatus(active.status, next)) { toast.error("Closed defects must be reopened before changing state."); return; } update.mutate({ id: active.id, status: next as "open" }); }}><option value="open">Open</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="reopened">Reopened</option><option value="closed">Closed</option></select></div><div className="detail-facts"><div><small>ASSIGNEE</small><b>{active.assignee}</b></div><div><small>ENVIRONMENT</small><b>{active.environment}</b></div><div><small>PRIORITY</small><b>{active.priority}</b></div><div><small>CREATED</small><b>{dateText(active.createdAt)}</b></div></div><div className="evidence-box"><p className="eyebrow">Reproduction context</p><p>{active.reproductionSteps}</p></div><Button onClick={() => analyze.mutate({ title: active.title, errorMessage: active.actualBehavior || undefined })} disabled={analyze.isPending} className="ai-analyze-button">{analyze.isPending ? <Loader2 className="spin" /> : <Sparkles />} {analyze.isPending ? "Analyzing evidence…" : "Analyze with AI"}</Button>{analyze.data && <div className="analysis-result"><div className="analysis-title"><BrainCircuit /><div><p className="eyebrow">AI root-cause analysis · {analyze.data.source}</p><h3>Probable dependency contract mismatch</h3></div><span>{analyze.data.confidence}% confidence</span></div><p><b>Root cause.</b> {analyze.data.rootCause}</p><div className="analysis-columns"><div><small>AFFECTED COMPONENT</small><b>{analyze.data.affectedComponent}</b><small>RECOMMENDED INVESTIGATION</small><p>{analyze.data.investigation}</p></div><div><small>SUGGESTED FIX</small><p>{analyze.data.suggestedFix}</p><small>REGRESSION TESTS TO ADD</small><ul>{analyze.data.regressionTests.map((test: string) => <li key={test}>{test}</li>)}</ul></div></div></div>}</>}</section></div></div>; }

function Defects() { const { data, isLoading } = trpc.defects.list.useQuery(); const [activeId, setActiveId] = useState<number | null>(null); const active = data?.find(item => item.id === activeId) ?? data?.[0]; const update = trpc.defects.update.useMutation({ onSuccess: () => toast.success("Defect workflow updated"), onError: error => toast.error(error.message) }); const analyze = trpc.ai.analyzeDefect.useMutation(); if (isLoading || !active) return <WorkspaceLoading />; return <div className="workspace-section"><SectionHeading eyebrow="Defect operations" title="Defects" description="Move quickly from a quality signal to responsible triage, evidence, and root-cause direction." /><div className="defect-layout"><section className="panel defect-list">{(data ?? []).map(defect => <button className={cn("defect-item", active.id === defect.id && "selected")} onClick={() => { setActiveId(defect.id); analyze.reset(); }} key={defect.id}><div><span className={cn("severity-bar", defect.severity)} /><div><small>{defect.key} · {defect.environment}</small><b>{defect.title}</b><span>{defect.assignee || "Unassigned"}</span></div></div><StatusPill value={defect.status} /></button>)}</section><section className="defect-detail"><div className="detail-header"><div><div className="detail-kicker"><span className={cn("priority-chip", active.severity)}>{active.severity}</span><span>{active.key}</span></div><h2>{active.title}</h2><p>{active.description}</p></div><DefectStatusSelect status={active.status} onChange={next => update.mutate({ id: active.id, status: next as "open" })} onBlocked={() => toast.error("Closed defects must be reopened before changing state.")} /></div><div className="detail-facts"><div><small>ASSIGNEE</small><b>{active.assignee}</b></div><div><small>ENVIRONMENT</small><b>{active.environment}</b></div><div><small>PRIORITY</small><b>{active.priority}</b></div><div><small>CREATED</small><b>{dateText(active.createdAt)}</b></div></div><div className="evidence-box"><p className="eyebrow">Reproduction context</p><p>{active.reproductionSteps}</p></div><Button onClick={() => analyze.mutate({ title: active.title, errorMessage: active.actualBehavior || undefined })} disabled={analyze.isPending} className="ai-analyze-button">{analyze.isPending ? <Loader2 className="spin" /> : <Sparkles />} {analyze.isPending ? "Analyzing evidence…" : "Analyze with AI"}</Button>{analyze.data && <div className="analysis-result"><p><b>Root cause.</b> {analyze.data.rootCause}</p><p><b>Suggested fix.</b> {analyze.data.suggestedFix}</p></div>}</section></div></div>; }

function FailureIntelligence() { const { data, isLoading, error } = trpc.overview.get.useQuery(); if (isLoading) return <WorkspaceLoading />; if (error || !data) return <div className="workspace-loading">Failure intelligence is temporarily unavailable. Please retry.</div>; const groups = data.failureGroups.map((group, index) => ({ name: group.name, freq: group.value, first: `Run ${Math.max(1, index + 1)}`, last: index === 0 ? "18 min ago" : `${index + 1}h ago`, tests: Math.max(2, Math.round(group.value / 2.5)), action: group.name === "Authentication" ? "Compare session revocation cache behavior across pods." : group.name === "API timeout" ? "Profile payment-provider fallback and extend contract timeout coverage." : group.name === "Validation" ? "Align optional field normalization between web and API clients." : "Move unstable selectors to durable data-test contracts." })); return <div className="workspace-section"><SectionHeading eyebrow="Pattern detection" title="AI Failure Intelligence" description="Group recurring execution failures into investigation-ready clusters instead of one-off symptoms." /><div className="intelligence-hero"><div><p className="eyebrow">QUALITYFORGE CLASSIFICATION ENGINE</p><h2>{groups.reduce((total, group) => total + group.freq, 0)}% of observed failures are repeat patterns.</h2><p>Live execution groups help eliminate root causes once and reduce investigation churn from run to run.</p></div><div className="cluster-meter"><b>{groups.length}</b><span>active patterns</span><i /></div></div><div className="intelligence-grid">{groups.map((group, index) => <article className="failure-card" key={group.name}><div><span className={cn("cluster-number", `cluster-${index}`)}>0{index + 1}</span><StatusPill value={index === 0 ? "high impact" : "watch"} /></div><h3>{group.name}</h3><div className="failure-metrics"><span><b>{group.freq}</b> occurrences</span><span><b>{group.tests}</b> affected tests</span></div><p><small>FIRST SEEN</small>{group.first} <small>LAST SEEN</small>{group.last}</p><div className="recommendation"><Sparkles /><p>{group.action}</p></div><button onClick={() => toast.message(`${group.name} investigation opened.`)}>Open investigation <ArrowRight /></button></article>)}</div></div>; }

function Pipelines() { const { data, isLoading } = trpc.pipelines.list.useQuery(); const [selected, setSelected] = useState(0); const [running, setRunning] = useState(false); const run = data?.[selected]; const runPipeline = () => { setRunning(true); setTimeout(() => { setRunning(false); toast.success("Pipeline completed with quality-gate evidence refreshed."); }, 1400); }; return <div className="workspace-section"><SectionHeading eyebrow="Delivery control" title="CI/CD Quality Gate" description="See the build chain, quality evidence, and promotion decision in one release-aware view." actions={<Button onClick={runPipeline} disabled={running} className="primary-button">{running ? <Loader2 className="spin" /> : <Play />} {running ? "Running pipeline…" : "Run pipeline"}</Button>} /><div className="pipeline-layout"><section className="panel pipeline-list"><div className="panel-heading"><div><h3>Pipeline runs</h3><p>{running ? "New run is in progress" : "Latest delivery activity"}</p></div></div>{isLoading ? <WorkspaceLoading /> : data?.map((item, index) => <button onClick={() => setSelected(index)} className={cn("pipeline-run", selected === index && "selected")} key={item.id}><div><b>{item.branch}</b><small>{item.commit} · {dateText(item.createdAt)}</small></div><StatusPill value={running && index === selected ? "running" : item.qualityGate} /></button>)}</section><section className="pipeline-detail">{run && <><div className="pipeline-summary"><div><p className="eyebrow">{run.branch} · {run.commit}</p><h2>Atlas deploy quality gate</h2><p>Automated quality rules evaluate the evidence before delivery moves forward.</p></div><div className="gate-status"><small>QUALITY GATE</small><StatusPill value={running ? "running" : run.qualityGate} /><b>{running ? "in progress" : `${Math.floor(run.durationSeconds / 60)}m ${run.durationSeconds % 60}s`}</b></div></div><div className="stage-flow">{run.stages.map((stage, index) => <div className="stage-row" key={stage.name}><span className={cn("stage-state", running && index === 5 ? "running" : stage.status)}>{running && index === 5 ? <Loader2 className="spin" /> : stage.status === "passed" ? <Check /> : stage.status === "failed" ? <X /> : <Loader2 className={stage.status === "running" ? "spin" : ""} />}</span><div><b>{stage.name}</b><small>{stage.timestamp} · {stage.duration}</small></div><span className="stage-log">{running && index === 5 ? "Executing pipeline stage…" : stage.log}</span>{index !== run.stages.length - 1 && <i />}</div>)}</div><div className="quality-rules"><div><b>Quality gate rules</b><span>PASS RATE ≥ 90%</span><span>COVERAGE ≥ 85%</span><span>CRITICAL DEFECTS = 0</span><span>REGRESSION FAILURES ≤ 1</span></div><p><AlertTriangle /> Promotion remains {run.qualityGate === "blocked" ? "blocked until the failed UI test and linked defect are resolved." : "controlled by the evidence shown above."}</p></div></>}</section></div></div>; }

function Releases() { const { data, isLoading } = trpc.overview.get.useQuery(); if (isLoading || !data) return <WorkspaceLoading />; return <div className="workspace-section"><SectionHeading eyebrow="Delivery decision" title="Release Readiness" description="A legible, traceable verdict that turns quality evidence into a confident release decision." actions={<Button onClick={() => toast.message("Release decision recorded in the demo audit trail.")} className="primary-button"><Check /> Approve with mitigation</Button>} /><div className="readiness-layout"><section className="readiness-score"><div className="score-dial"><div><b>{data.metrics.releaseScore}</b><span>/100</span></div></div><p className="eyebrow">2026.08.12-rc.3 · Staging</p><h2>Near-ready for production.</h2><p>Strong system health and coverage offset one payment confirmation defect that has a clear owner and remediation path.</p><StatusPill value={data.metrics.releaseState} /></section><section className="panel readiness-evidence"><div className="panel-heading"><div><h3>Decision evidence</h3><p>Weighted release signals</p></div></div>{[{ label: "Test pass rate", value: data.metrics.passRate, note: "Threshold 90%" }, { label: "Automation coverage", value: data.metrics.coverage, note: "Threshold 85%" }, { label: "API health", value: data.metrics.apiHealth, note: "Threshold 95%" }, { label: "Deployment stability", value: 92, note: "No rollbacks in 14 days" }].map(item => <div className="evidence-row" key={item.label}><div><b>{item.label}</b><small>{item.note}</small></div><div className="evidence-bar"><i style={{ width: `${item.value}%` }} /></div><b>{item.value}%</b></div>)}<div className="decision-note"><AlertTriangle /><div><b>Open mitigation</b><p>The checkout payment contract mismatch is classified as critical. Production promotion requires either a verified fix or an explicit exception owner.</p></div></div></section></div><section className="panel release-history"><div className="panel-heading"><div><h3>Recent releases</h3><p>Decision record across projects</p></div></div>{data.releases.map(release => <div className="release-row" key={release.id}><div><b>{release.version}</b><small>{release.environment} · {release.summary}</small></div><strong>{release.score}</strong><StatusPill value={release.status} /></div>)}</section></div>; }

function Analytics() { const { data, isLoading } = trpc.overview.get.useQuery(); if (isLoading || !data) return <WorkspaceLoading />; const coverage = data.coverageTrend.map((value, index) => ({ label: `Run ${index + 1}`, coverage: value, score: data.qualityTrend[index] })); return <div className="workspace-section"><SectionHeading eyebrow="Quality analytics" title="Engineering analytics" description="Connect test stability, automation investment, operational health, and release quality over time." actions={<Button variant="outline" onClick={() => toast.message("Filters are available in the full product.")} className="soft-button">All projects <ChevronRight /></Button>} /><div className="analytics-cards"><MetricCard label="Mean time to resolution" value="3.8h" detail="-41m vs prior sprint" accent="cyan" icon={Gauge} /><MetricCard label="Regression stability" value="94.6%" detail="2 flaky tests quarantined" accent="violet" icon={Activity} /><MetricCard label="Median API response" value="284ms" detail="Within 350ms performance budget" accent="green" icon={Network} /></div><section className="panel large-chart"><div className="panel-heading"><div><h3>Coverage and quality converge</h3><p>Automation expansion is improving release confidence.</p></div><div className="chart-legend"><span><i className="cyan" /> Quality score</span><span><i className="violet" /> Automation coverage</span></div></div><ResponsiveContainer width="100%" height={310}><AreaChart data={coverage}><defs><linearGradient id="coverageArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#9e9cf5" stopOpacity={0.26}/><stop offset="100%" stopColor="#9e9cf5" stopOpacity={0}/></linearGradient></defs><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: "#81909b", fontSize: 11 }}/><YAxis domain={[60, 100]} axisLine={false} tickLine={false} tick={{ fill: "#81909b", fontSize: 11 }}/><Tooltip contentStyle={{ background: "#10171d", border: "1px solid #26333e", borderRadius: 10 }} /><Area type="monotone" dataKey="score" stroke="#75dde6" strokeWidth={2.5} fill="transparent" /><Area type="monotone" dataKey="coverage" stroke="#a9a8ff" strokeWidth={2.5} fill="url(#coverageArea)" /></AreaChart></ResponsiveContainer></section><div className="analysis-note"><BrainCircuit /><div><p className="eyebrow">AI observation</p><h3>Checkout UI selectors are the clearest stability drag.</h3><p>Prioritize durable data-test contracts in the checkout funnel to improve the regression signal without increasing suite runtime.</p></div><Button variant="outline" onClick={() => toast.message("AI observation pinned to the project insight feed.")}>Pin insight</Button></div></div>; }

function Team() { const [location] = useLocation(); const protectedView = location.startsWith("/workspace"); const demo = trpc.team.demoList.useQuery(undefined, { enabled: !protectedView }); const secure = trpc.team.list.useQuery(undefined, { enabled: protectedView }); const data = protectedView ? secure.data : demo.data; const isLoading = protectedView ? secure.isLoading : demo.isLoading; const error = protectedView ? secure.error : demo.error; if (error) return <div className="workspace-loading">Team data requires an administrator session.</div>; return <div className="workspace-section"><SectionHeading eyebrow="Shared ownership" title="Team collaboration" description="Surface responsibilities, quality work, and recent operational context for every contributor." actions={<Button onClick={() => toast.message("Team invitations are represented in this demo workspace.")} className="primary-button"><Plus /> Invite teammate</Button>} /><div className="team-grid">{isLoading ? <WorkspaceLoading /> : data?.map((member, index) => <article className="member-card" key={member.id}><div className={cn("member-avatar", member.avatarTone)}>{member.name.split(" ").map(word => word[0]).join("")}</div><div><h3>{member.name}</h3><p>{member.role}</p></div><StatusPill value={index % 4 === 0 ? "reviewing" : "active"} /><div className="member-load"><span><b>{index + 1}</b> assigned defects</span><span><b>{4 + index * 2}</b> test cases</span></div><button onClick={() => toast.message(`Opened ${member.name}'s activity timeline.`)}>View activity <ArrowRight /></button></article>)}</div><section className="panel activity-panel"><div className="panel-heading"><div><h3>Team activity</h3><p>Latest quality collaboration events</p></div></div>{["Noah added a regression test for card authorization recovery", "Elena moved DEF-148 to In Progress", "Maya approved a release exception review", "Ari recorded a new analytics API baseline"].map((activity, index) => <div className="activity-row" key={activity}><span>{index + 1}</span><p>{activity}</p><small>{index * 18 + 9}m ago</small></div>)}</section></div>; }

function Audit() { const [location] = useLocation(); const protectedView = location.startsWith("/workspace"); const demo = trpc.audit.demoList.useQuery(undefined, { enabled: !protectedView }); const secure = trpc.audit.list.useQuery(undefined, { enabled: protectedView }); const data = protectedView ? secure.data : demo.data; const isLoading = protectedView ? secure.isLoading : demo.isLoading; const error = protectedView ? secure.error : demo.error; if (error) return <div className="workspace-loading">Audit data requires an administrator session.</div>; return <div className="workspace-section"><SectionHeading eyebrow="Governance trail" title="Audit log" description="Trace release decisions, quality changes, AI requests, and user activity through a persistent operational record." /><section className="table-panel audit-table"><div className="table-head audit-grid"><span>Actor</span><span>Action</span><span>Resource</span><span>Device / IP</span><span>Timestamp</span></div>{isLoading ? <WorkspaceLoading /> : data?.map(log => <div className="table-row audit-grid" key={log.id}><div className="audit-actor"><span>{log.actor.split(" ").map(word => word[0]).join("").slice(0, 2)}</span><b>{log.actor}</b></div><span>{log.action}</span><span className="audit-resource">{log.resource}</span><span>{log.ipDevice}</span><span>{dateText(log.createdAt)}</span></div>)}</section></div>; }

function Assistant() { const { data } = trpc.overview.get.useQuery(); const [question, setQuestion] = useState("Why did the checkout regression fail?"); const [messages, setMessages] = useState<Array<{ role: "user" | "assistant"; text: string }>>([{ role: "assistant", text: "I’m ready with current release, test, defect, and pipeline context. Ask for an investigation, a test plan, or a release summary." }]); const liveContext = data ? `Release candidate 2026.08.12-rc.3 has a ${data.metrics.releaseScore} readiness score, ${data.metrics.passRate}% test pass rate, ${data.metrics.apiHealth}% API health, ${data.metrics.coverage}% coverage, ${data.metrics.criticalDefects} unresolved critical defects, ${data.defects.length} recently triaged defects, and a ${data.metrics.releaseState} quality gate.` : "Workspace signals are loading."; const ask = trpc.ai.ask.useMutation({ onSuccess: response => setMessages(current => [...current, { role: "assistant", text: response.answer }]), onError: error => { setMessages(current => [...current, { role: "assistant", text: "I could not complete that analysis right now. Please retry after checking the workspace connection." }]); toast.error(error.message); } }); const submit = () => { if (!question.trim() || ask.isPending) return; setMessages(current => [...current, { role: "user", text: question }]); ask.mutate({ question, context: liveContext }); setQuestion(""); }; return <div className="workspace-section assistant-page"><SectionHeading eyebrow="Context-aware support" title="Forge Assistant" description="A focused quality engineering copilot with the current workspace signal in view." /><div className="assistant-layout"><section className="assistant-chat"><div className="assistant-intro"><span><Bot /></span><div><p className="eyebrow">QUALITYFORGE AI</p><h2>What should we investigate?</h2><p>Ask about a failure, generate coverage, summarize a release, or locate risk.</p></div></div><div className="suggestion-row">{["Which defects are blocking release?", "Show unstable tests", "Generate API tests for checkout"].map(item => <button onClick={() => setQuestion(item)} key={item}>{item}</button>)}</div><div className="message-stack">{messages.map((message, index) => <article className={cn("assistant-message", message.role)} key={index}><span>{message.role === "assistant" ? <Bot /> : "MC"}</span><p>{message.text}</p></article>)}{ask.isPending && <article className="assistant-message assistant"><span><Bot /></span><p><Loader2 className="spin" /> Reading quality signals…</p></article>}</div><div className="chat-input"><Textarea value={question} onChange={event => setQuestion(event.target.value)} onKeyDown={event => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); submit(); } }} placeholder="Ask Forge Assistant about this workspace…" /><Button onClick={submit} disabled={ask.isPending || !question.trim()}><ArrowRight /></Button></div><small className="assistant-disclaimer">QualityForge AI can guide investigation; release decisions remain accountable to your team.</small></section><aside className="assistant-context"><p className="eyebrow">CURRENT CONTEXT</p><h3>Atlas Commerce</h3><div><span>Release score</span><b>{data?.metrics.releaseScore ?? "—"} / 100</b></div><div><span>Open critical defects</span><b className="danger-text">{data?.metrics.criticalDefects ?? "—"}</b></div><div><span>Test pass rate</span><b>{data?.metrics.passRate ?? "—"}%</b></div><div><span>Pipeline gate</span><StatusPill value={data?.metrics.releaseState ?? "loading"} /></div><hr/><p className="eyebrow">QUICK ACTIONS</p><button onClick={() => setQuestion("Summarize the release with risks and recommended actions.")}>Summarize release <ArrowRight /></button><button onClick={() => setQuestion("What tests have the highest failure rate?")}>Find failure hotspots <ArrowRight /></button></aside></div></div>; }

function WorkspaceLoading() { return <div className="workspace-loading"><Loader2 className="spin" /><span>Loading QualityForge signals…</span></div>; }

export function AuthenticatedWorkspace() {
  const { loading, isAuthenticated } = useAuth();
  if (loading) return <WorkspaceLoading />;
  if (!isAuthenticated) return <div className="auth-wall"><div><span className="brand-mark"><span className="brand-mark-core" /></span><p className="eyebrow">Private QualityForge workspace</p><h1>Sign in to continue.</h1><p>Use your secure Manus identity to access protected quality intelligence workflows.</p><Button onClick={() => startLogin()} className="primary-button">Sign in securely <ArrowRight /></Button></div></div>;
  return <Workspace />;
}
